        self.val = val
        self.left = left
        self.right = right


from bisect import bisect_left


class TreeCursor:
    def __init__(self, root: TreeNode | None):
        # Flatten the whole tree once, in order (iteratively, so a deep tree
        # can't hit the recursion limit).
        self.values = []
        stack, node = [], root
        while stack or node:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            self.values.append(node.val)
            node = node.right
        self.i = 0  # index of the next value to return

    def next(self) -> int | None:
        if self.i == len(self.values):
            return None
        self.i += 1
        return self.values[self.i - 1]

    def peek(self) -> int | None:
        return self.values[self.i] if self.i < len(self.values) else None

    def has_next(self) -> bool:
        return self.i < len(self.values)

    def skip_to(self, x: int) -> int | None:
        # max(): a cursor never moves backwards.
        self.i = max(self.i, bisect_left(self.values, x))
        return self.peek()

