use std::cell::RefCell;
use std::rc::Rc;

struct TreeCursor {
    values: Vec<i32>,
    i: usize, // index of the next value to return
}

impl TreeCursor {
    fn new(root: Option<Rc<RefCell<TreeNode>>>) -> Self {
        // Flatten the whole tree once, in order.
        let mut values = Vec::new();
        let (mut stack, mut node) = (Vec::new(), root);
        while node.is_some() || !stack.is_empty() {
            while let Some(n) = node {
                node = n.borrow().left.clone();
                stack.push(n);
            }
            let n = stack.pop().unwrap();
            values.push(n.borrow().val);
            node = n.borrow().right.clone();
        }
        TreeCursor { values, i: 0 }
    }

    fn next(&mut self) -> Option<i32> {
        let v = *self.values.get(self.i)?;
        self.i += 1;
        Some(v)
    }

    fn peek(&self) -> Option<i32> {
        self.values.get(self.i).copied()
    }

    fn has_next(&self) -> bool {
        self.i < self.values.len()
    }

    fn skip_to(&mut self, x: i32) -> Option<i32> {
        // max(): a cursor never moves backwards.
        self.i = self.i.max(self.values.partition_point(|&v| v < x));
        self.peek()
    }
}

