class TreeNode:
    def __init__(self, val: int = 0, left: "TreeNode | None" = None, right: "TreeNode | None" = None):
        self.val = val
        self.left = left
        self.right = right


class TreeCursor:
    def __init__(self, root: TreeNode | None):
        self.root = root
        # The nodes still to return whose left subtrees are already done, deepest
        # on top: the top is always the next value.
        self.stack = []
        self._descend(root)

    def _descend(self, node: TreeNode | None) -> None:
        while node:
            self.stack.append(node)
            node = node.left

    def next(self) -> int | None:
        if not self.stack:
            return None
        node = self.stack.pop()
        # Its right subtree comes next, starting from that subtree's smallest.
        self._descend(node.right)
        return node.val

    def peek(self) -> int | None:
        return self.stack[-1].val if self.stack else None

    def has_next(self) -> bool:
        return bool(self.stack)

    def skip_to(self, x: int) -> int | None:
        if not self.stack or self.stack[-1].val >= x:
            return self.peek()  # nothing left is below x
        # Re-seek from the root, as a search for x would walk: the nodes >= x on
        # that path are exactly the stack a fresh cursor would have at x.
        self.stack = []
        node = self.root
        while node:
            if node.val >= x:
                self.stack.append(node)
                node = node.left
            else:
                node = node.right
        return self.peek()

