use std::cell::RefCell;
use std::rc::Rc;

type Link = Option<Rc<RefCell<TreeNode>>>;

struct TreeCursor {
    root: Link,
    // The nodes still to return whose left subtrees are already done, deepest on
    // top: the top is always the next value.
    stack: Vec<Rc<RefCell<TreeNode>>>,
}

impl TreeCursor {
    fn new(root: Link) -> Self {
        let mut cursor = TreeCursor { root: root.clone(), stack: Vec::new() };
        cursor.descend(root);
        cursor
    }

    fn descend(&mut self, mut node: Link) {
        while let Some(n) = node {
            node = n.borrow().left.clone();
            self.stack.push(n);
        }
    }

    fn next(&mut self) -> Option<i32> {
        let node = self.stack.pop()?;
        let (val, right) = {
            let n = node.borrow();
            (n.val, n.right.clone())
        };
        // Its right subtree comes next, starting from that subtree's smallest.
        self.descend(right);
        Some(val)
    }

    fn peek(&self) -> Option<i32> {
        self.stack.last().map(|n| n.borrow().val)
    }

    fn has_next(&self) -> bool {
        !self.stack.is_empty()
    }

    fn skip_to(&mut self, x: i32) -> Option<i32> {
        match self.peek() {
            Some(v) if v < x => {}
            unchanged => return unchanged, // nothing left is below x
        }
        // Re-seek from the root, as a search for x would walk: the nodes >= x on
        // that path are exactly the stack a fresh cursor would have at x.
        self.stack.clear();
        let mut node = self.root.clone();
        while let Some(n) = node {
            let (val, left, right) = {
                let b = n.borrow();
                (b.val, b.left.clone(), b.right.clone())
            };
            if val >= x {
                self.stack.push(n);
                node = left;
            } else {
                node = right;
            }
        }
        self.peek()
    }
}
